1059→// runUninstall completely removes Entire from the repository.
1060→func runUninstall(w, errW io.Writer, force bool) error {
1061→	// Check if we're in a git repository
1062→	if _, err := paths.RepoRoot(); err != nil {
1063→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
1064→		return NewSilentError(errors.New("not a git repository"))
1065→	}
1066→
1067→	// Gather counts for display
1068→	sessionStateCount := countSessionStates()
1069→	shadowBranchCount := countShadowBranches()
1070→	gitHooksInstalled := strategy.IsGitHookInstalled()
1071→	claudeHooksInstalled := checkClaudeCodeHooksInstalled()
1072→	geminiHooksInstalled := checkGeminiCLIHooksInstalled()
1073→	opencodeHooksInstalled := checkOpenCodeHooksInstalled()
1074→	entireDirExists := checkEntireDirExists()
1075→
1076→	// Check if there's anything to uninstall
1077→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
1078→		shadowBranchCount == 0 && !claudeHooksInstalled && !geminiHooksInstalled && !opencodeHooksInstalled {
1079→		fmt.Fprintln(w, "Entire is not installed in this repository.")
1080→		return nil
1081→	}
1082→
1083→	// Show confirmation prompt unless --force
1084→	if !force {
1085→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
1086→		if entireDirExists {
1087→			fmt.Fprintln(w, "  - .entire/ directory")
1088→		}
1089→		if gitHooksInstalled {
1090→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
1091→		}
1092→		if sessionStateCount > 0 {
1093→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
1094→		}
1095→		if shadowBranchCount > 0 {
1096→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
1097→		}
1098→		var agentNames []string
1099→		if claudeHooksInstalled {
1100→			agentNames = append(agentNames, "Claude Code")
1101→		}
1102→		if geminiHooksInstalled {
1103→			agentNames = append(agentNames, "Gemini CLI")
1104→		}
1105→		if opencodeHooksInstalled {
1106→			agentNames = append(agentNames, "OpenCode")
1107→		}
1108→		if len(agentNames) > 0 {
1109→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(agentNames, ", "))
1110→		}
1111→		fmt.Fprintln(w)
1112→
1113→		var confirmed bool
1114→		form := NewAccessibleForm(
1115→			huh.NewGroup(
1116→				huh.NewConfirm().
1117→					Title("Are you sure you want to uninstall Entire?").
1118→					Affirmative("Yes, uninstall").
1119→					Negative("Cancel").
1120→					Value(&confirmed),
1121→			),
1122→		)
1123→
1124→		if err := form.Run(); err != nil {
1125→			return fmt.Errorf("confirmation cancelled: %w", err)
1126→		}
1127→
1128→		if !confirmed {
1129→			fmt.Fprintln(w, "Uninstall cancelled.")
1130→			return nil
1131→		}
1132→	}
1133→
1134→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1135→
1136→	// 1. Remove agent hooks (lowest risk)
1137→	if err := removeAgentHooks(w); err != nil {
1138→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1139→	}
1140→
1141→	// 2. Remove git hooks
1142→	removed, err := strategy.RemoveGitHook()
1143→	if err != nil {
1144→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1145→	} else if removed > 0 {
1146→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1147→	}
1148→
1149→	// 3. Remove session state files
1150→	statesRemoved, err := removeAllSessionStates()
1151→	if err != nil {
1152→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
