 615→func TestShellCompletionTarget(t *testing.T) {
 616→	tests := []struct {
 617→		name             string
 618→		shell            string
 619→		createBashProf   bool
 620→		wantShell        string
 621→		wantRCBase       string // basename of rc file
 622→		wantCompletion   string
 623→		wantErrUnsupport bool
 624→	}{
 625→		{
 626→			name:           "zsh",
 627→			shell:          "/bin/zsh",
 628→			wantShell:      "Zsh",
 629→			wantRCBase:     ".zshrc",
 630→			wantCompletion: "autoload -Uz compinit && compinit && source <(entire completion zsh)",
 631→		},
 632→		{
 633→			name:           "bash_no_profile",
 634→			shell:          "/bin/bash",
 635→			wantShell:      "Bash",
 636→			wantRCBase:     ".bashrc",
 637→			wantCompletion: "source <(entire completion bash)",
 638→		},
 639→		{
 640→			name:           "bash_with_profile",
 641→			shell:          "/bin/bash",
 642→			createBashProf: true,
 643→			wantShell:      "Bash",
 644→			wantRCBase:     ".bash_profile",
 645→			wantCompletion: "source <(entire completion bash)",
 646→		},
 647→		{
 648→			name:           "fish",
 649→			shell:          "/usr/bin/fish",
 650→			wantShell:      "Fish",
 651→			wantRCBase:     filepath.Join(".config", "fish", "config.fish"),
 652→			wantCompletion: "entire completion fish | source",
 653→		},
 654→		{
 655→			name:             "empty_shell",
 656→			shell:            "",
 657→			wantErrUnsupport: true,
 658→		},
 659→	}
 660→
 661→	for _, tt := range tests {
 662→		t.Run(tt.name, func(t *testing.T) {
 663→			home := t.TempDir()
 664→			t.Setenv("HOME", home)
 665→			t.Setenv("SHELL", tt.shell)
 666→
 667→			if tt.createBashProf {
 668→				if err := os.WriteFile(filepath.Join(home, ".bash_profile"), []byte(""), 0o644); err != nil {
 669→					t.Fatal(err)
 670→				}
 671→			}
 672→
 673→			shellName, rcFile, completion, err := shellCompletionTarget()
 674→
 675→			if tt.wantErrUnsupport {
 676→				if !errors.Is(err, errUnsupportedShell) {
 677→					t.Fatalf("got err=%v, want errUnsupportedShell", err)
 678→				}
 679→				return
 680→			}
 681→			if err != nil {
 682→				t.Fatalf("unexpected error: %v", err)
 683→			}
 684→			if shellName != tt.wantShell {
 685→				t.Errorf("shellName = %q, want %q", shellName, tt.wantShell)
 686→			}
 687→			wantRC := filepath.Join(home, tt.wantRCBase)
 688→			if rcFile != wantRC {
 689→				t.Errorf("rcFile = %q, want %q", rcFile, wantRC)
 690→			}
 691→			if completion != tt.wantCompletion {
 692→				t.Errorf("completion = %q, want %q", completion, tt.wantCompletion)
 693→			}
 694→		})
 695→	}
