 698→func TestAppendShellCompletion(t *testing.T) {
 699→	tests := []struct {
 700→		name           string
 701→		rcFileRelPath  string
 702→		completionLine string
 703→		preExisting    string // existing content in rc file; empty means file doesn't exist
 704→		createParent   bool   // whether parent dir already exists
 705→	}{
 706→		{
 707→			name:           "zsh_new_file",
 708→			rcFileRelPath:  ".zshrc",
 709→			completionLine: "source <(entire completion zsh)",
 710→			createParent:   true,
 711→		},
 712→		{
 713→			name:           "zsh_existing_file",
 714→			rcFileRelPath:  ".zshrc",
 715→			completionLine: "source <(entire completion zsh)",
 716→			preExisting:    "# existing zshrc content\n",
 717→			createParent:   true,
 718→		},
 719→		{
 720→			name:           "fish_no_parent_dir",
 721→			rcFileRelPath:  filepath.Join(".config", "fish", "config.fish"),
 722→			completionLine: "entire completion fish | source",
 723→			createParent:   false,
 724→		},
 725→		{
 726→			name:           "fish_existing_dir",
 727→			rcFileRelPath:  filepath.Join(".config", "fish", "config.fish"),
 728→			completionLine: "entire completion fish | source",
 729→			createParent:   true,
 730→		},
 731→	}
 732→
 733→	for _, tt := range tests {
 734→		t.Run(tt.name, func(t *testing.T) {
 735→			home := t.TempDir()
 736→			rcFile := filepath.Join(home, tt.rcFileRelPath)
 737→
 738→			if tt.createParent {
 739→				if err := os.MkdirAll(filepath.Dir(rcFile), 0o755); err != nil {
 740→					t.Fatal(err)
 741→				}
 742→			}
 743→			if tt.preExisting != "" {
 744→				if err := os.WriteFile(rcFile, []byte(tt.preExisting), 0o644); err != nil {
 745→					t.Fatal(err)
 746→				}
 747→			}
 748→
 749→			if err := appendShellCompletion(rcFile, tt.completionLine); err != nil {
 750→				t.Fatalf("appendShellCompletion() error: %v", err)
 751→			}
 752→
 753→			// Verify the file was created and contains the completion line.
 754→			data, err := os.ReadFile(rcFile)
 755→			if err != nil {
 756→				t.Fatalf("reading rc file: %v", err)
 757→			}
 758→			content := string(data)
 759→
 760→			if !strings.Contains(content, shellCompletionComment) {
 761→				t.Errorf("rc file missing comment %q", shellCompletionComment)
