 767→				t.Errorf("pre-existing content was overwritten")
 768→			}
 769→
 770→			// Verify parent directory permissions.
 771→			info, err := os.Stat(filepath.Dir(rcFile))
 772→			if err != nil {
 773→				t.Fatalf("stat parent dir: %v", err)
 774→			}
 775→			if !info.IsDir() {
 776→				t.Fatal("parent path is not a directory")
 777→			}
 778→		})
